#include <bits/stdc++.h>
using namespace std;

using ll = long long;

const int MXN = 2e5+1, LOG = 18;

int n, k, w[MXN], c[MXN], par[LOG][MXN], stt[MXN], timer, h[MXN], cnt[MXN], col[MXN];
vector<int> g[MXN], cols[MXN];
bool mark[MXN], cutie[MXN];

void dfs(int v) {
    stt[v] = timer++;
    for(int i=1; i<LOG; i++) par[i][v] = par[i-1][par[i-1][v]];
    for(int u : g[v])
        if(u!=par[0][v]) {
            h[u] = h[v]+1;
            par[0][u] = v;
            dfs(u);
        }
}

inline int jump(int v, int d) {
    for(int i=0; i<LOG; i++)
        if(d>>i&1)
            v = par[i][v];
    return v;
}

inline int LCA(int u, int v) {
    if(h[u]<h[v]) swap(u, v);
    u = jump(u, h[u]-h[v]);
    if(u==v) return u;
    for(int i=LOG-1; i>=0; i--)
        if(par[i][u]!=par[i][v])
            u = par[i][u], v = par[i][v];
    return par[0][u];
}

void DFS(int v, int cc) {
    if(c[v]) cc=c[v];
    else c[v]=cc;
    for(int u : g[v])
        if(u!=par[0][v])
            DFS(u, cc);
}

void Main() {
    cin >> n >> k;
    timer = 0;
    for(int i=1; i<=n; i++) {
        cnt[i] = 0;
