        cutie[i] = 0;
        cols[i].clear();
    }
    for(int i=1; i<=n; i++) cin >> w[i];
    for(int i=1; i<=n; i++) cin >> c[i], cols[c[i]].push_back(i);
    for(int i=1, u,v; i<n; i++) {
        cin >> u >> v;
        g[u].push_back(v);
        g[v].push_back(u);
    }
    bool fnd=0;
    for(int i=1; i<=n; i++)
        fnd |= c[i];
    if(!fnd) {
        cout << "0\n";
        for(int i=1; i<=n; i++) cout << "1 ";
        cout << '\n';
        return;
    }
    dfs(1);
    for(int i=1; i<=k; i++) {
        sort(cols[i].begin(), cols[i].end(), [&](int u, int v) {
            return stt[u]<stt[v];
        });
        vector<int> V;
        for(int j=0, u, v, lca; j+1<int(cols[i].size()); j++) {
            u = cols[i][j], v = cols[i][j+1], lca = LCA(u, v);
            if(!mark[lca]) {
                if(c[lca]) {
                    if(c[lca] != i) cutie[lca] = 1;
                    continue;
                }
                mark[lca] = 1;
                cnt[lca]++;
                col[lca] = i;
                V.push_back(lca);
            }
        }
        for(int v : V) mark[v] = 0;
        cols[i].clear();
    }
    ll val=0;
    for(int i=1; i<=n; i++) {
        if(cutie[i] || cnt[i]>1) val += w[i];
        if(!c[i] && cnt[i]==1) c[i] = col[i];
