#include <bits/stdc++.h>
using namespace std;

using ll = long long;

const int MXN = 4e5+5;
const int MOD = 1e9+7;

ll power(ll a, ll b) {
    ll res = 1;
    while(b) {
        if(b&1) (res *= a) %= MOD;
        (a *= a) %= MOD;
        b >>= 1;
    }
    return res;
}

ll F[MXN], I[MXN];

void prep() {
    F[0] = 1;
    for(int i=1; i<MXN; i++) F[i] = F[i-1]*i%MOD;
    I[0] = I[1] = 1;
    for(int i=2; i<MXN; i++) I[i] = (MOD-MOD/i)*I[MOD%i]%MOD;
    for(int i=2; i<MXN; i++) (I[i] *= I[i-1]) %= MOD;
}
ll C(int n, int r) {
    return r<0 || r>n ? 0 : F[n]*I[r]%MOD*I[n-r]%MOD;
}
ll g(int n, int m, int l) {
    if(n==0) return m==0;
    ll ans = 0;
    for(int t=0; t<=n && t*(l+1)<=m; t++)
        (ans += C(n,t)*C(m+n-1-t*(l+1), n-1)%MOD*(t%2 ? MOD-1 : 1)%MOD) %= MOD;
    return ans;
}

void solve() {
    ll n, m, ans=0;
    cin >> n >> m;
    ll inv = power(n-1, MOD-2);
    for(ll x=0; x<=m; x++) {
        ll g1 = g(n-1, m-x, x), g2 = g(n-2, m-2*x, x);
        (ans += x*(g1+g2*(n-1)%MOD)) %= MOD;
        ll bad=0;
        (bad += (m-x)*g1%MOD*inv) %= MOD;
        (bad += x*g2) %= MOD;
        (bad += (m-2*x)*g2) %= MOD;
        (ans += MOD-bad) %= MOD;
    }
    cout << ans << '\n';
}

int32_t main() {
    cin.tie(0); cout.tie(0); ios_base::sync_with_stdio(0);
    prep();
    int tc;
    cin >> tc;
    while(tc--) solve();
    return 0;
}

